import{_ as o,l as r,o as e,c as l,v as i,p as m,x as n,d as p,i as s,S as d}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"Maxmin 期望效用","description":"","frontmatter":{"title":"Maxmin 期望效用","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/maxmin-eu.md","filePath":"econ/maxmin-eu.md","lastUpdated":1789023840000}'),E={name:"econ/maxmin-eu.md"};function c(h,a,u,_,C,B){const t=r("Mermaid");return e(),l("div",null,[a[1]||(a[1]=i('<h1 id="maxmin-期望效用" tabindex="-1">Maxmin 期望效用 <a class="header-anchor" href="#maxmin-期望效用" aria-label="Permalink to &quot;Maxmin 期望效用&quot;">​</a></h1><div class="epigraph"><p>先验不是一个点，而是一组概率。厌恶模糊的人，按这组里最坏的那个期望效用做选择。</p><footer>—— 据 Gilboa and Schmeidler, Maxmin Expected Utility with Non-unique Prior, Journal of Mathematical Economics, 1989 整理</footer></div><p><a href="/econ/ellsberg-ambiguity">上一课</a>把未知权重与已知 \\(\\pi\\) 的风险分开，并声明主干仍用 \\(\\mathbb{E}u\\)。本课不重做两只罐子，也不把 Borch 再写一遍。缺口是：埃尔斯伯格只给出反例，没有给出替代表示。Gilboa–Schmeidler 用多先验上的最大最小</p> \\[V(f)=\\min_{p\\in C}\\int u(f)\\,\\mathrm{d}p \\]<p>把模糊厌恶收成公理化对象。本课把这条表示钉死，同时再声明一次：后课保险、占优、状态价格、宏观，默认仍走单一 \\(\\pi\\) 的期望效用；Maxmin 是已标明的边界，不升格为新主干。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>上一课指出：若坚持单一主观概率，罐子选择不一致；若放弃，常用弱化是多先验。缺口是写出那条弱化，而不是再描述实验。Gilboa–Schmeidler 在 Anscombe–Aumann 菜单上以<strong>确定性独立</strong>替换独立性，并加上不确定厌恶（凸组合优于端点的混合），得到紧凸先验集 \\(C\\subseteq\\Delta(S)\\) 与仿射 \\(u\\)，使 \\(V\\) 即上式。\\(C\\) 退化为单点时，回到主观期望效用。\\(C\\) 越大，越厌恶模糊。</p><p>这与凹性无关：\\(u\\) 仍可凹，风险厌恶在每个 \\(p\\) 内部照旧；\\(\\min\\) 额外打击的是先验的未知。不要把 Maxmin 读成「更凹的 \\(u\\)」。</p><h3 id="最坏先验不是-mps" tabindex="-1">最坏先验不是 MPS <a class="header-anchor" href="#最坏先验不是-mps" aria-label="Permalink to &quot;最坏先验不是 MPS&quot;">​</a></h3><p>对 \\(C\\) 取 \\(\\min\\)，不是在某一客观 \\(F\\) 上做均值保持展开。罐子二没有给出 \\(F\\)。把 \\(C\\) 里最散的 \\(p\\) 当成「更大风险」，是偷换对象——上一课已经禁过。本课表示承认：决策者仿佛与敌对的自然对弈，自然从 \\(C\\) 里挑 \\(p\\)。规范市场理论不必采用这场对弈。</p><p><span class="marginnote">确定性独立：与确定结果混合时，独立性保留；与不确定行为混合时，独立性放弃。这正是为了容纳埃尔斯伯格，又保住 \\(u\\) 的仿射。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>工作策略与阿莱课对称：问卷与表示当对照，市场公式默认单一 \\(\\pi\\)。若某后课改用 Maxmin 或鲁棒控制，必须显式写出 \\(C\\)，不能把 \\(q_s/\\pi_s\\) 里的 \\(\\pi\\) 偷偷换成「最坏 \\(p\\)」。检验表示：看是否存在凸 \\(C\\) 使选择等于最坏期望；本课不估计 \\(C\\)。</p><p>光滑模糊、乘子偏好、变分偏好是同一家族的放松，\\(\\min\\) 换成对先验的惩罚。本课只取 GS 的 \\(\\min\\)，以免把不确定课序写成决策理论综述。下一课程换对象：生产集 \\(Y\\) 没有先验，也不要写成 \\(C\\)。</p>',14)),(e(),m(d,null,{default:n(()=>[s(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20ELL%5B%22%E4%B8%8A%E4%B8%80%E8%AF%BE%EF%BC%9A%CF%80%20%E6%9C%AA%E7%9F%A5%22%5D%20--%3E%20GS%5B%22GS%EF%BC%9Amin_%7Bp%20%E2%88%88%20C%7D%20E_p%20u%22%5D%0A%20%20GS%20--%3E%20SEU%5B%22C%20%E5%8D%95%E7%82%B9%EF%BC%9A%E5%9B%9E%E5%88%B0%20EU%22%5D%0A%20%20GS%20--%3E%20KEEP%5B%22%E4%B8%BB%E5%B9%B2%E4%BB%8D%E7%94%A8%E5%8D%95%E4%B8%80%20%CF%80%20%E7%9A%84%20E%20u%22%5D%0A%20%20KEEP%20--%3E%20LATER%5B%22%E4%B8%8B%E8%AF%BE%E7%A8%8B%EF%BC%9A%E7%94%9F%E4%BA%A7%E9%9B%86%20Y%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<p>本课不把 Maxmin 引进状态价格。完全市场的 \\(q\\) 默认仍对已知 \\(\\pi\\) 记账。也不把 \\(C\\) 写成限价簿上「不确定谁报价」。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为何是 \\(\\min\\)：不确定厌恶公理要求，把两个行为混在一起（对先验更确定）不差于两端。最坏期望对 \\(C\\) 的凸组合是线性的，对行为的混合则偏好凸性，正好匹配。\\(u\\) 仍来自对客观彩票的 vNM；多出来的只是先验集。因此风险厌恶与模糊厌恶可以共存：同一 \\(u\\) 凹，同时 \\(C\\) 不是单点。</p><p>对后课的含义不变。规范层：Borch、SOSD、Arrow 价格继续按 \\(\\mathbb{E}u\\) 写。描述层：实验室回避未知权重，用 \\(C\\) 记录，不拿来改写 \\(r_A\\)。本栏宏观与公司金融走规范层。若要把鲁棒性写进欧拉，那是另课声明，不是本课自动生效。</p><p><span class="marginnote">Gilboa and Schmeidler 1989 针对 Anscombe–Aumann 的主观混合。Savage 风格的纯主观菜单上，多先验表示更绕。引用不要把罐子写成前景理论附录。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>\\(C\\) 从哪来，公理不说。事后把所有拒绝的 \\(p\\) 塞进 \\(C\\)，表示会变得没有限制。市场数据很少识别 \\(C\\)，这是主干保留 EU 的经验理由，不是无视公理。Maxmin 对某些信息更新不平滑（最坏先验跳跃），后课贝叶斯学习默认单一先验。</p><p>也不要把 Maxmin 当生产技术。厂商课的不确定性若出现，先写成状态依存的 \\(Y_s\\)，仍默认 \\(\\pi\\)。本课把不确定课序收束在对照表示上，不把生产集改写成先验集。</p><p>后课默认：工作表示仍是单一 \\(\\pi\\) 上的 \\(\\mathbb{E}u\\)；Gilboa–Schmeidler 是埃尔斯伯格的形式化对照。见到 \\(\\min_{p\\in C}\\)，当作显式偏离主干，不是默认的分担与占优。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>多先验 Maxmin：\\(V=\\min_{p\\in C}\\mathbb{E}_p u\\)；确定性独立加不确定厌恶。</li><li>\\(C\\) 单点即主观 EU；模糊厌恶是 \\(C\\) 变大，不是更凹。</li><li>最坏先验不是 SOSD 的展形；对象是未知权重。</li><li>主干仍用期望效用；本课只完成上一课未展开的表示。</li><li>出处：Gilboa and Schmeidler, <em>Journal of Mathematical Economics</em>, 1989。</li></ul>',11))])}const x=o(E,[["render",c]]);export{A as __pageData,x as default};
